nta.declaration:
const int n = 6;          // breytanlegt board siez

int total_moves = 0;
//int[0, 1000] total_time;
clock total_time;

int[0,20] grid[n][n];    // í hverjum reit getur verið bíll með id, eða 0 sem er empty reitur

// Boolean fall sem skilar true ef id er á stað (x,y) og getur farið á næsta stað (dx, dy)
bool canMove(int id, int x, int y, int dx, int dy, int len, bool horiz) {
    if (horiz) {
        // Fyrir lárétta bíla, tjekka  hvort að næsti reitur er laus.
        // Ef hægri: dx > 0, skoða reit x+len (einum framar)
        // Ef vinstri: dx < 0, skoða reit x-1 (einum aftar)
        int nextX = (dx > 0) ? x + len : x - 1;
        if (nextX < 0 || nextX >= n) return false;  // ef hann skildi fara útfyrir kassann.
        return grid[y][nextX] == 0;                  // skilar True ef næsti reitur er tómur, þá má hann fara áfram
    } else {
        // sama fyrir lóðrétta bíla, nema með y.
        int nextY = (dy > 0) ? y + len : y - 1;
        if (nextY < 0 || nextY >= n) return false;
        return grid[nextY][x] == 0;
    }
}

// Stillir upp bílum frá Local Declarations í initializer með bíla ids
void place_car(int id, int len, int x, int y, bool horiz) {
    // mikilvægt að initializa rétt inn í local initializer
    int i;
    for (i = 0; i < len; i++) {
        if (horiz && x + i < n)      grid[y][x + i] = id;  // fer frá vinstri til hægri
        else if (!horiz && y + i < n) grid[y + i][x] = id; // fer frá topp niður að botn
    }
}

// uppfærir grid eftir að einhver hreyfir sig
// og tæmir gamla reitin eftir að gamli færir sig-
void move_car(int id, int x, int y, int dx, int dy, int len, bool horiz) {
    if (horiz) {
        if (dx > 0 && x + len < n) { // fer til hægri
            grid[y][x] = 0;          // tæmir vinstra
            grid[y][x + len] = id;   // tekur hægra megin

        } else if (dx < 0 && x - 1 >= 0) { // fer til vinstri
            grid[y][x + len - 1] = 0; // tæmir hægra megin
            grid[y][x - 1] = id;      // tekur vinstra megin
        }
    } else {
        if (dy > 0 && y + len < n) {   // fer niður
            grid[y][x] = 0;           // tæmir ofan
            grid[y + len][x] = id;    // tekur neðri

        } else if (dy < 0 && y - 1 >= 0) { // fer upp
            grid[y + len - 1][x] = 0; // tæmir neðri
            grid[y - 1][x] = id;      // tekur efri
        }
    }
}

nta.system:
inits = initializer();
red       = horizontalCar(1,  2, 3, 2, 3);
green     = horizontalCar(2,  2, 0, 0, 3);
orange    = horizontalCar(3,  2, 2, 0, 3);
blue      = verticalCar  (4,  2, 4, 0, 3);
pink      = verticalCar  (5,  2, 2, 1, 3);
yellow    = verticalCar  (6,  3, 5, 1, 5);
purple    = verticalCar  (7,  2, 1, 2, 3);
magenta   = verticalCar  (8,  3, 0, 3, 5);
darkgreen = horizontalCar(9,  2, 3, 3, 3);
gray      = verticalCar  (10, 2, 3, 4, 3);
beige     = horizontalCar(11, 2, 4, 4, 3);
brown     = horizontalCar(12, 2, 1, 5, 3);
black     = horizontalCar(13, 2, 4, 5, 3);

system inits, red, green, orange, blue, pink, yellow,
       purple, magenta, darkgreen, gray, beige, brown, black;
